import {preparePlayerLooks} from './native-studio.js';

// Original presentation pointers are verified against the opened ROM.
export const PRESENTATION_TEXTS=[
 ['intro.gender','Boy / girl question',0x1ce6e1,[0x133b8c],'intro'],
 ['intro.welcome','Professor welcome',0x1ce984,[0x133648],'intro'],
 ['intro.world','World introduction',0x1cea12,[0x1336ec],'intro'],
 ['intro.creatures','Creatures introduction',0x1cea1e,[0x133860],'intro'],
 ['intro.profession','Pets, battles and profession',0x1cea57,[0x1338f4],'intro'],
 ['intro.self','Tell me about yourself',0x1ceac9,[0x133a7c],'intro'],
 ['intro.name','Player name question',0x1ceaf6,[0x133e64,0x133fd4],'intro'],
 ['intro.confirm','Player name confirmation',0x1ceb1f,[0x134208],'intro'],
 ['intro.rival','Rival introduction',0x1ceb3a,[0x1344cc],'intro'],
 ['intro.rivalname','Rival name question',0x1ceb9d,[0x134034],'intro'],
 ['intro.rivalconfirm','Rival name confirmation',0x1cebc1,[0x134250],'intro'],
 ['intro.rivalfinal','Rival final confirmation',0x1cebd1,[0x134354],'intro'],
 ['intro.adventure','Final adventure introduction',0x1cec00,[0x13461c],'intro'],
 ['intro.boy','First player choice label',0x433f37,[0x133cf0],'intro',10],
 ['intro.girl','Second player choice label',0x433f3b,[0x133cf4],'intro',10],
 ['intro.controls','Controls heading',0x433ed0,[0x132c90],'intro',20],
 ['credits.heading','Staff heading',0x43b33c,[0x0f7a18],'credits'],
 ['credits.director.role','Director role',0x43b37c,[0x432760],'credits'],
 ['credits.director.name','Director name',0x43b38c,[0x432764],'credits'],
 ['credits.art.role','Art / battle director roles',0x43b3a4,[0x43276c],'credits'],
 ['credits.art.name','Art / battle director names',0x43b3c8,[0x432770],'credits'],
 ['credits.lead.role','Leader roles',0x43b3ec,[0x432778],'credits'],
 ['credits.lead.name','Leader names',0x43b428,[0x43277c],'credits'],
 ['credits.program.role','Programmers role',0x43b458,[0x432784],'credits'],
 ['credits.program.name','Programmer names',0x43b46c,[0x432788],'credits'],
 ['credits.system.role','System programmer role',0x43b4b8,[0x432790],'credits'],
 ['credits.system.name','System programmer names',0x43b4d4,[0x432794],'credits'],
 ['menu.newgame','New game menu label',0x433c12,[0x0f6dc,0x0f75c,0x0f82c],'labels',12],
 ['menu.continue','Continue menu label',0x433c1b,[0x0f758,0x0f828],'labels',12],
 ['menu.options','Options heading',0x437f70,[0x08c734],'labels',16]
].map(([id,name,address,refs,kind,maxChars])=>({id,name,address,refs,kind,maxChars}));
export function presentationChanges(project){return Object.keys(readAuthoring(project).presentation?.texts||{}).length;}
export function presentationTextIssues(slot,text,original){const issues=[];try{encodedText(text);}catch(e){issues.push(e.message);}if(slot.maxChars&&text.length>slot.maxChars)issues.push('Keep this menu label within '+slot.maxChars+' characters.');if(slot.kind==='credits'&&(String(text).match(/\n|\\n/g)||[]).length!==(String(original).match(/\n|\\n/g)||[]).length)issues.push('Keep the source credit block’s blank lines and line count for native alignment.');return issues;}
export function installPresentation(project,reader,hash,output){const values=readAuthoring(project).presentation?.texts||{},reports=[];if(!Object.keys(values).length)return reports;for(const [id,record]of Object.entries(values)){const slot=PRESENTATION_TEXTS.find(s=>s.id===id);if(!slot)throw Error('Unknown native presentation text slot.');if(record.sourceHash!==hash)throw Error('A presentation text belongs to another source ROM.');if(slot.refs.some(at=>reader.u32(at)!==0x08000000+slot.address))throw Error('The original '+slot.name+' pointer failed verification.');const original=decodeScriptText(reader.bytes,slot.address).text,issues=presentationTextIssues(slot,record.text,original);if(issues.length)throw Error(slot.name+': '+issues.join(' '));const at=output.allocate(encodedText(record.text),'Presentation text: '+slot.name);for(const ref of slot.refs)output.int(ref,0x08000000+at);reports.push('Presentation: '+slot.name);}return reports;}

export function presentationWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={tab:'intro',playing:false,raf:null};
 const data=()=>authoring(api.project()).presentation;
 async function open(tab=state.tab){state.tab=tab;let context=null;if(api.session())try{context=await api.game().context();}catch{}const verified=!!context&&PRESENTATION_TEXTS.some(s=>s.refs.every(at=>context.reader.valid(at,4)&&context.reader.u32(at)===0x08000000+s.address));api.modal('Opening, credits & presentation',`<div class="studio-tabs">${[['intro','Opening text'],['credits','Credits'],['labels','Menu labels'],['timeline','Visual timelines'],['looks','Player looks']].map(([id,name])=>`<button data-presentation-tab="${id}" type="button" class="${state.tab===id?'active':''}">${name}</button>`).join('')}</div><div id="presentationContent"></div>`,null,'Done');document.querySelectorAll('[data-presentation-tab]').forEach(b=>b.onclick=()=>open(b.dataset.presentationTab));
  if(['intro','credits','labels'].includes(tab)){$('#presentationContent').innerHTML=`<p>${tab==='intro'?'Edit the professor opening, naming prompts and two existing player-choice labels.':tab==='credits'?'Edit verified staff text blocks. Preserve their line structure to retain native alignment.':'Change existing menu wording. Custom settings are built in Game maker → Options.'}</p>${!verified?'<p class="studio-status needs-attention">These opening / credits text pointers have not been identified in the opened ROM. Visual timelines and player-look drafts remain available; ROM dialogue and native menu text use separate readers.</p>':''}${PRESENTATION_TEXTS.filter(s=>s.kind===tab).map(s=>`<button type="button" data-presentation-text="${s.id}" class="studio-record" ${context&&s.refs.every(at=>context.reader.valid(at,4)&&context.reader.u32(at)===0x08000000+s.address)?'':'disabled'}><span><b>${esc(s.name)}</b><small>${data().texts[s.id]?'Edited in project':'Source text'}</small></span></button>`).join('')}`;document.querySelectorAll('[data-presentation-text]').forEach(b=>b.onclick=()=>editText(PRESENTATION_TEXTS.find(s=>s.id===b.dataset.presentationText),context));}
  else if(tab==='timeline')timelineBrowser();else looks();
 }
 function editText(slot,context){const original=decodeScriptText(context.reader.bytes,slot.address).text.replace(/\\n/g,'\n'),value=data().texts[slot.id]?.text??original;api.modal(slot.name,`<label>Text<textarea id="presentationText" maxlength="8000" rows="8">${esc(value)}</textarea></label><p class="hint-line">Keep tokens such as {PLAYER}, {RIVAL} and explicit \\p page breaks. Native screen geometry stays the same.</p><div id="presentationTextStatus"></div><div class="dialogue-preview" id="presentationTextPreview"></div><button id="presentationRestore" type="button">Restore source wording</button>`,()=>{const text=$('#presentationText').value,issues=presentationTextIssues(slot,text,original);api.change(()=>data().texts[slot.id]={sourceHash:context.hash,text});api.toast(issues.length?'Text draft saved. Resolve the highlighted layout / encoding issues before compiling.':'Presentation text saved to project.');},'Save text draft');const preview=()=>{const text=$('#presentationText').value,issues=presentationTextIssues(slot,text,original);$('#presentationTextStatus').className='studio-status '+(issues.length?'needs-attention':'ready');$('#presentationTextStatus').textContent=issues.join(' ')||'Text encoding / layout checks passed';$('#presentationTextPreview').textContent=text.replace(/\\[npl]/g,'\n');};$('#presentationText').oninput=preview;preview();$('#presentationRestore').onclick=()=>{api.change(()=>delete data().texts[slot.id]);open(slot.kind);};}
 function timelineBrowser(){const rows=data().scenes||[];$('#presentationContent').innerHTML='<p>Compose image movement, dialogue, fades and music cues. Install one timeline as a native opening before the title. A/Start skips it; native openings can last up to 60 seconds.</p><button id="presentationNewTimeline" type="button" class="primary">＋ New timeline</button>'+rows.map(s=>`<button data-timeline-edit="${s.id}" class="studio-record" type="button"><span><b>${esc(s.name)}</b><small>${s.steps.length} stages · preview / export</small></span></button>`).join('');$('#presentationNewTimeline').onclick=()=>editTimeline();document.querySelectorAll('[data-timeline-edit]').forEach(b=>b.onclick=()=>editTimeline(rows.find(s=>s.id===b.dataset.timelineEdit)));}
 function editTimeline(old=null,draft=null){const scene=draft||structuredClone(old||{id:uid(),name:'Opening sequence',steps:[]});api.modal('Timeline · '+scene.name,`<label>Name<input id="timelineName" maxlength="120" value="${esc(scene.name)}"></label><label class="check"><input id="timelineNative" type="checkbox" ${data().nativeTimelineId===scene.id?'checked':''}> Install this opening / splash in the ROM</label><div class="studio-actions"><button id="timelinePreview" type="button">▶ Preview</button><button id="timelineExport" type="button">Export timeline pack</button></div><div id="timelineSteps"></div><div class="studio-actions"><select id="timelineType">${[['image','Image / sprite'],['text','Dialogue / scrawl'],['fade','Fade'],['wait','Wait'],['music','Music cue'],['clear','Clear stage']].map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select><button id="timelineAdd" type="button">＋ Add stage</button></div><input id="timelineImageFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><p class="hint-line">Preview canvas is 240 × 160. Image stages can animate from X/Y to End X/Y. Native openings use 256-colour frames at 20 fps and preserve music cues. Map cutscenes use the visual scene editor.</p>`,()=>{scene.name=$('#timelineName').value.trim()||scene.name;save();},'Save timeline');const save=()=>api.change(()=>{const rows=data().scenes??=[],i=rows.findIndex(s=>s.id===scene.id);if(i<0)rows.push(structuredClone(scene));else rows[i]=structuredClone(scene);if($('#timelineNative')?.checked)data().nativeTimelineId=scene.id;else if(data().nativeTimelineId===scene.id)delete data().nativeTimelineId;});
  function collect(){scene.name=$('#timelineName').value.trim()||scene.name;document.querySelectorAll('[data-timeline-row]').forEach(el=>{const s=scene.steps[+el.dataset.timelineRow];el.querySelectorAll('[data-time-field]').forEach(input=>s[input.dataset.timeField]=input.type==='number'?+input.value:input.value);});}
  function draw(){$('#timelineSteps').innerHTML=scene.steps.map((s,i)=>`<details class="scene-section" data-timeline-row="${i}" open><summary>${i+1}. ${esc(s.type)}</summary><label>Duration (frames, 60 ≈ 1 second)<input data-time-field="frames" type="number" min="1" max="3600" value="${s.frames||60}"></label>${s.type==='text'?`<label>Text<textarea data-time-field="text">${esc(s.text||'')}</textarea></label>`:s.type==='image'?`<label>Artwork<select data-time-field="assetId"><option value="">Choose later…</option>${api.project().assets.map(a=>`<option value="${a.id}" ${s.assetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label><div class="studio-actions"><button data-time-image="${i}" type="button">Upload image</button></div><div class="field-row">${['x','y','endX','endY'].map(k=>`<label>${k}<input data-time-field="${k}" type="number" value="${s[k]||0}"></label>`).join('')}</div>`:s.type==='fade'?`<label>Fade<select data-time-field="mode"><option value="out" ${s.mode!=='in'?'selected':''}>To black</option><option value="in" ${s.mode==='in'?'selected':''}>From black</option></select></label>`:s.type==='music'?`<label>Track<select data-time-field="trackId"><option value="">Choose later…</option>${readAuthoring(api.project()).music.map(t=>`<option value="${t.id}" ${s.trackId===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label>`:''}<div class="studio-actions"><button data-time-up="${i}" type="button" ${i?'':'disabled'}>↑</button><button data-time-remove="${i}" type="button">Remove stage</button></div></details>`).join('');document.querySelectorAll('[data-time-remove]').forEach(b=>b.onclick=()=>{collect();scene.steps.splice(+b.dataset.timeRemove,1);draw();});document.querySelectorAll('[data-time-up]').forEach(b=>b.onclick=()=>{collect();const i=+b.dataset.timeUp;[scene.steps[i-1],scene.steps[i]]=[scene.steps[i],scene.steps[i-1]];draw();});document.querySelectorAll('[data-time-image]').forEach(b=>b.onclick=()=>{collect();state.imageStage=+b.dataset.timeImage;$('#timelineImageFile').click();});}
  draw();$('#timelineAdd').onclick=()=>{collect();if(scene.steps.length>=64)throw Error('Keep one timeline within 64 stages.');scene.steps.push({type:$('#timelineType').value,frames:60,x:0,y:0,endX:0,endY:0,text:''});draw();};$('#timelineImageFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>12e6)throw Error('Use an image below 12 MB.');const src=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);}),image=new Image();image.src=src;await image.decode();const canvas=document.createElement('canvas');canvas.width=Math.min(512,image.width);canvas.height=Math.min(512,image.height);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const asset={id:uid(),name:file.name,width:canvas.width,height:canvas.height,tileSize:16,data:canvas.toDataURL('image/png')};api.change(()=>{if(api.project().assets.length>=512)throw Error('The image limit was reached.');api.project().assets.push(asset);});scene.steps[state.imageStage].assetId=asset.id;draw();}catch(error){api.error(error);}};$('#timelinePreview').onclick=()=>{collect();preview(scene,()=>editTimeline(old,scene));};$('#timelineExport').onclick=()=>{collect();const ids=new Set(scene.steps.map(s=>s.assetId).filter(Boolean));api.save(new Blob([JSON.stringify({format:'pokebacon-presentation',version:1,scene,assets:api.project().assets.filter(a=>ids.has(a.id)),music:readAuthoring(api.project()).music.filter(t=>scene.steps.some(s=>s.trackId===t.id))})],{type:'application/json'}),scene.name.replace(/[^a-z0-9]+/gi,'_')+'.timeline.json');};
 }
 async function preview(scene,back){state.playing=true;api.modal('Preview · '+scene.name,'<canvas id="presentationCanvas" width="240" height="160" class="presentation-canvas"></canvas><p id="presentationStageInfo"></p><button id="presentationStop" type="button">Stop preview</button>',()=>{state.playing=false;back();return false;},'Back');$('#presentationStop').onclick=()=>state.playing=false;const canvas=$('#presentationCanvas'),c=canvas.getContext('2d'),layers=[],draw=()=>{c.fillStyle='#000';c.fillRect(0,0,240,160);for(const layer of layers)c.drawImage(layer.image,layer.x,layer.y);};for(const [index,s]of scene.steps.entries()){if(!state.playing||!canvas.isConnected)break;$('#presentationStageInfo').textContent='Stage '+(index+1)+' / '+scene.steps.length+' · '+s.type;let image=null;if(s.type==='image'&&s.assetId){image=await api.ensureImage(s.assetId);layers.push({image,x:+s.x||0,y:+s.y||0});}if(s.type==='clear')layers.length=0;if(s.type==='music'&&s.trackId)api.music().previewId(s.trackId).catch(api.error);const duration=Math.max(1,Math.min(3600,+s.frames||60))/60*1000,start=performance.now();await new Promise(resolve=>{const frame=()=>{if(!state.playing||!canvas.isConnected){resolve();return;}const t=Math.min(1,(performance.now()-start)/duration);if(image){const layer=layers.at(-1);layer.x=(+s.x||0)+((+s.endX||0)-(+s.x||0))*t;layer.y=(+s.y||0)+((+s.endY||0)-(+s.y||0))*t;}draw();if(s.type==='fade'){c.fillStyle='rgba(0,0,0,'+(s.mode==='in'?1-t:t)+')';c.fillRect(0,0,240,160);}if(s.type==='text'){c.fillStyle='#f8f8f8';c.fillRect(6,110,228,44);c.fillStyle='#203024';c.font='10px monospace';const lines=String(s.text||'').split(/\n|\\n/);lines.slice(0,3).forEach((line,i)=>c.fillText(line.slice(0,36),12,123+i*12));}if(t<1)state.raf=requestAnimationFrame(frame);else resolve();};frame();});}state.playing=false;api.music().stop();}
 function looks(){const p=data(),groups=api.project().spriteStudio?.groups.filter(g=>g.views.overworld)||[],rows=p.playerLooks||[];$('#presentationContent').innerHTML=`<p>Add named player appearances to the new-game selector and Options → PROJECT. Their overworld art uses independent graphics; cycling, surfing, fishing, battle and naming portraits use the chosen original base avatar.</p><label class="check"><input id="playerLooksInstall" type="checkbox" ${p.installPlayerLooks?'checked':''} ${rows.length?'':'disabled'}> Install the expanded player selector</label><button id="playerLookAdd" type="button">＋ Player appearance</button>${rows.map(l=>`<div class="studio-record"><span><b>${esc(l.name)}</b><small>${esc(groups.find(g=>g.id===l.spriteGroupId)?.name||'Sprite group missing')} · ${l.enabled===false?'draft':'native selection'}</small></span><button data-player-look="${l.id}" type="button">Edit</button></div>`).join('')}<p class="hint-line">Use a 16 × 32 view with one static frame or nine directional frames. The original two avatars stay available. L/R changes pages in the native selector. Appearance values persist with the game save.</p>`;$('#playerLookAdd').onclick=()=>editLook();$('#playerLooksInstall').onchange=e=>{api.change(()=>{p.installPlayerLooks=e.target.checked;if(p.installPlayerLooks)preparePlayerLooks(api.project());});};document.querySelectorAll('[data-player-look]').forEach(b=>b.onclick=()=>editLook(rows.find(l=>l.id===b.dataset.playerLook)));}
 function editLook(old=null){const p=data(),groups=api.project().spriteStudio?.groups.filter(g=>g.views.overworld?.width===16&&g.views.overworld?.height===32)||[];api.modal(old?'Edit player appearance':'Player appearance',`<label>Name<input id="playerLookName" maxlength="24" value="${esc(old?.name||'')}" placeholder="Rocket uniform"></label><label>Sprite group<select id="playerLookGroup">${groups.map(g=>`<option value="${g.id}" ${old?.spriteGroupId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><label>Base avatar for other actions<select id="playerLookBase"><option value="0" ${old?.baseGender!==1?'selected':''}>Original boy</option><option value="1" ${old?.baseGender===1?'selected':''}>Original girl</option></select></label><label class="check"><input id="playerLookNative" type="checkbox" ${old?.enabled===false?'':'checked'}> Include in the native appearance selector</label><p>Overworld colours fit the source field palettes. Keep this as a draft by unticking the selector option.</p>${old?'<button id="playerLookDelete" type="button" class="danger">Remove appearance</button>':''}`,()=>{const spriteGroupId=$('#playerLookGroup').value;if(!spriteGroupId)throw Error('Create a 16 × 32 character overworld group first.');const value={id:old?.id||uid(),name:$('#playerLookName').value.trim()||'Player look',spriteGroupId,baseGender:+$('#playerLookBase').value,enabled:$('#playerLookNative').checked};api.change(()=>{p.playerLooks??=[];if(!old&&p.playerLooks.length>=16)throw Error('Use up to 16 custom player appearances.');if(old)Object.assign(old,value);else p.playerLooks.push(value);if(value.enabled){p.installPlayerLooks=true;preparePlayerLooks(api.project());}});open('looks');return false;},'Save appearance');if(old)$('#playerLookDelete').onclick=()=>{api.change(()=>p.playerLooks=p.playerLooks.filter(l=>l.id!==old.id));open('looks');};}
 return{state,open,preview};
}
